export function slowDouble(x) {
  return new Promise((r) => setTimeout(() => r(x * 2), 20));
}

export async function poolMap(items, limit, fn) {
  const out = new Array(items.length);
  let cursor = 0;
  async function worker() {
    while (cursor < items.length) {
      const i = cursor++;
      out[i] = await fn(items[i], i);
    }
  }
  const workers = [];
  for (let i = 0; i < Math.min(limit, items.length); i++) workers.push(worker());
  await Promise.all(workers);
  return out;
}

export function runCommand(input) {
  const tokens = String(input).trim().split(/\s+/).filter(Boolean);
  const command = tokens[0];
  const flags = tokens.slice(1).filter((t) => t.startsWith('-'));
  let base;
  if (!command || command === 'help') base = 'Usage: app <command>';
  else if (command === 'status') base = 'ok';
  else base = 'unknown: ' + command;
  return flags.length ? base + ' ' + flags.join(' ') : base;
}

