export function createRegistry() {
  const plugins = new Map();
  return {
    register(name, handler) {
      plugins.set(name, handler);
    },
    run(name, ...args) {
      if (!plugins.has(name)) throw new Error('no plugin: ' + name);
      return plugins.get(name)(...args);
    },
    names() {
      return [...plugins.keys()].sort();
    },
  };
}

const registry = createRegistry();
export { registry };
